package structure

import "testing"

func (r Record) TestOnly() bool { return true }
func TestStructureFixture(t *testing.T) {
 r := Record{Name: "before", secret: "hidden"}
 r.Rename("after")
 n, ok := r.Lookup("word")
 callback := Callback(func(value string) (int, error) { return len(value), nil })
 count, err := callback.Invoke("go")
 if r.Name != "after" || n != 4 || !ok || Counter(7).Count() != 7 || (Table[int]{Item: 9}).ItemValue() != 9 || count != 2 || err != nil || !r.TestOnly() || CgoAnswer() != 42 || AfterUnicode() != 6 { t.Fatal("structure fixture semantics") }
}

